template <typename UnionPtrType>
UkmEntryPtr UkmEntry::Clone() const {
  switch (tag_) {
    case Tag::kNonCompliantApi:
      return NewNonCompliantApi(
          mojo::Clone(*data_.non_compliant_api));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, UkmEntry>::value>::type*>
bool UkmEntry::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kNonCompliantApi:
      return mojo::Equals(*(data_.non_compliant_api), *(other.data_.non_compliant_api));
  }

  return false;
}
